INSERT INTO public.glossary_terms
  ("id", "term", "aliases", "definition", "learnMoreUrl", "isActive", "createdAt", "updatedAt")
VALUES
  ('cg2615_c1557c36b5a841500d197c', 'Access to clean cooking fuels', ARRAY[]::text[], 'The proportion of a population primarily using cooking fuels and technologies that meet specified household air-pollution standards.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c731a544263735a52cbda8', 'Access to electricity', ARRAY[]::text[], 'The share of people who have electricity available for use at home under the definition used in the indicator.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_dd927ec32ee09c49b1900a', 'Account servicing payment service provider', ARRAY[]::text[], 'A bank or other provider that holds a customer''s payment account and executes transactions initiated from that account.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f2d7012eb48267ed5022e3', 'Accredited investor', ARRAY[]::text[], 'An investor who meets specified financial or professional criteria for participating in certain private securities offerings under US rules.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7b1c689e2506b32d961ef9', 'Accrued interest', ARRAY[]::text[], 'Interest that has accumulated on a debt security since the last payment date but has not yet been paid.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_bf73d8e148840773d6ebe6', 'Acquiring bank in card payments', ARRAY[]::text[], 'A financial institution that contracts with merchants to process card transactions and route payments to their accounts.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d7fa73f89860ad83090508', 'Active fund', ARRAY[]::text[], 'A pooled investment vehicle whose manager selects holdings with the aim of achieving an investment objective rather than mechanically following an index.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_87101f4d6be820fc999a74', 'Adjusted closing price', ARRAY[]::text[], 'A historical security price modified to reflect corporate actions such as dividends or share splits, enabling more meaningful return comparisons.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f7fc55f734d78f680abf22', 'Adjusted net savings', ARRAY[]::text[], 'Gross national savings after subtracting consumption of fixed capital, natural-resource depletion and pollution damage, and adding education expenditure under a specified methodology.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_315217584f31f7a6d2bd64', 'Adolescent fertility rate', ARRAY[]::text[], 'The number of live births to women aged 15–19 per 1,000 women in that age group during a year.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f195060b549c39410464e0', 'Adult literacy rate', ARRAY[]::text[], 'The share of adults meeting a statistical definition of basic reading and writing ability, with the reference age specified.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7b3be36da90f77e9984d36', 'Age dependency ratio', ARRAY[]::text[], 'The number of people in designated younger and older age groups relative to the working-age population.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_91c217890989719733993a', 'Agency bond', ARRAY[]::text[], 'A debt security issued or guaranteed by a government-sponsored or government-related organisation, with backing dependent on the issuer and security.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e3a2ff890018808dc7ba94', 'Agricultural land share', ARRAY[]::text[], 'The proportion of a country''s land used for arable farming, permanent crops or permanent pasture under a stated definition.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_66c9665a5bcd34e64a3daf', 'Agricultural value added', ARRAY[]::text[], 'The contribution of agriculture, forestry and fishing to GDP after subtracting intermediate inputs.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7fd6dddaf6fdf676f8edd2', 'Alternative investment', ARRAY[]::text[], 'An asset or strategy outside conventional listed shares, bonds and cash, such as private equity, hedge funds or certain commodities.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_91609af8cae37d1e3ee355', 'Alternative work arrangement', ARRAY[]::text[], 'Employment carried out through a temporary-help agency, contracting firm, on-call arrangement or independent contracting rather than a conventional permanent job.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_6273b7332a7d8895dfc909', 'American depositary receipt', ARRAY[]::text[], 'A negotiable certificate issued by a US depositary bank representing shares in a foreign company that can trade in US markets.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8030355d1e44c3f6d0f44b', 'Annual average index', ARRAY[]::text[], 'The average of an index''s twelve monthly observations during a calendar year, used to summarise the level of the index over that year.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_177fa5be5235f28cd22848', 'Annualised growth rate', ARRAY[]::text[], 'A rate expressing how quickly a variable would grow over twelve months if its observed shorter-period rate continued.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_763e7fffdd3c54efd05b50', 'Annuity', ARRAY[]::text[], 'A financial contract that provides payments according to agreed terms, sometimes for a specified number of years or for the recipient''s lifetime.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f3bb8eccd9657231832716', 'Arbitrage fund', ARRAY[]::text[], 'A fund pursuing returns from differences in prices or related securities across markets, with risks depending on its strategies.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b312c525e727628108d951', 'Ask price', ARRAY[]::text[], 'The price at which a seller or dealer is currently willing to sell a security or other asset.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4b12073f02ddb8f2d62860', 'Asset class', ARRAY[]::text[], 'A group of investments sharing broad characteristics and sources of risk, such as equities, government bonds or property.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_6cbbf8bd7383c66d668471', 'Atlas conversion method', ARRAY[]::text[], 'A World Bank method using smoothed exchange rates and inflation adjustments to convert national income figures into US dollars for country-income comparisons.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_991e1fb087207ec63441b9', 'Automated clearing house', ARRAY[]::text[], 'An electronic system that receives and processes large numbers of payment instructions, commonly settling them in batches.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9bd8ec42b97fcd801fc2ff', 'Average hourly earnings', ARRAY[]::text[], 'Total payroll earnings divided by paid hours for an identified group of employees, giving an average nominal wage measure.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e260e6924baeaac295b367', 'Average weekly hours', ARRAY[]::text[], 'The average number of hours worked or paid per employee during a specified week, according to a survey''s measurement rules.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_941259af1e4922714bf1c6', 'Back-end sales load', ARRAY[]::text[], 'A mutual fund fee charged when investors redeem shares, sometimes declining the longer the investor holds them.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_541a4771daa8f707ebe9c2', 'Balanced investment fund', ARRAY[]::text[], 'A fund that invests across both shares and bonds or other asset classes to combine potential growth and income.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c45944290085adafd9a559', 'Banking supervision', ARRAY[]::text[], 'The monitoring and enforcement of prudential requirements intended to ensure banks operate safely and manage risks appropriately.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c96fd2fe5bd008a258574e', 'Banking union', ARRAY[]::text[], 'The European framework for common supervision and resolution of banks in participating countries, supported by shared institutions.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d89f9e01cce4775fa04809', 'Bayes'' theorem', ARRAY[]::text[], 'A rule for updating the probability of a hypothesis after observing evidence, using prior probabilities and the likelihood of the evidence.', 'https://openstax.org/books/introductory-statistics-2e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_853ebe7d9d315a97742f62', 'Bear market rally', ARRAY[]::text[], 'A temporary increase in asset prices during a broader period of decline, which does not necessarily signal the end of the downturn.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_fe467eb8606e9001c9abdb', 'Benchmark index', ARRAY[]::text[], 'A market indicator used as a reference for judging an investment portfolio''s performance, risks or investment strategy.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_620aa4737d3d0caaa9afd9', 'Benchmark revision of employment', ARRAY[]::text[], 'An update to survey-based employment estimates using more complete administrative or census data, which may change previously reported levels.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8874857bd62a2b98451664', 'Beneficial ownership of securities', ARRAY[]::text[], 'The right to enjoy the economic benefits of securities even when they are registered in another person''s or institution''s name.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ec65acf5bb8e582291c8a9', 'Bernoulli distribution', ARRAY[]::text[], 'The distribution of a random variable that equals one with probability p and zero otherwise.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e1c111b7e7548cc9f08971', 'Bernoulli trial', ARRAY[]::text[], 'An experiment with two possible results, commonly success and failure, and a defined probability of success.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_07c0f1e60452d528274582', 'Bid price', ARRAY[]::text[], 'The price at which a buyer or dealer is currently willing to purchase a security or other asset.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_a47a7da8ee1e87185371f5', 'Binary variable', ARRAY[]::text[], 'A variable that takes one of two values, commonly coded zero and one to represent the absence or presence of a characteristic.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_cfe6dd0d6e3de8073ace90', 'Binomial distribution', ARRAY[]::text[], 'The probability distribution of the number of successes in a fixed number of independent Bernoulli trials with the same success probability.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_dee6c59c574cb9fa4b095b', 'Birth-death adjustment for businesses', ARRAY[]::text[], 'A statistical adjustment to payroll estimates that accounts for employment at newly created and closed businesses not yet fully represented in surveys.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_412101e6407a2692790f89', 'Bivariate regression', ARRAY[]::text[], 'A statistical regression model relating one outcome variable to one explanatory variable.', 'https://openstax.org/books/introductory-statistics-2e/pages/12-3-the-regression-equation', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_5b21b59db74c43669db4cc', 'Blinded experiment', ARRAY[]::text[], 'An experiment in which some participants or evaluators are not told the treatment assignment, reducing the influence of expectations on outcomes.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0219bfd66c243881f49bfe', 'Book value per share', ARRAY[]::text[], 'A company''s reported shareholder equity divided by outstanding ordinary shares, based on accounting values rather than market prices.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c850806c112eea2090c842', 'Box-and-whisker plot', ARRAY[]::text[], 'A display of a variable''s distribution showing the median, quartiles, whiskers and often potential outliers.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_963911ab80f352ce5ed755', 'Broadband subscription rate', ARRAY[]::text[], 'Fixed or mobile broadband subscriptions expressed relative to population or households under the chosen indicator definition.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9d1fbc13ee9dfda9446f9f', 'Broker-dealer', ARRAY[]::text[], 'A financial firm that acts as an agent executing securities trades for customers or buys and sells securities for its own account.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e1d1b7e5a247b389f8c065', 'Brokerage commission', ARRAY[]::text[], 'A charge paid to a broker for executing or arranging a transaction, which may be fixed or based on the amount traded.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_cec2a1d70eb47f8e02b44d', 'Business credit transfer', ARRAY[]::text[], 'A payment instruction transferring funds from a business''s account to another account through an authorised payment service.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9b79beb967e01966bdd0e3', 'Business employment dynamics', ARRAY[]::text[], 'Statistics describing how jobs are created and lost at establishments as firms expand, contract, open or close.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_77870f26f69bae3d244adc', 'Callable bond', ARRAY[]::text[], 'A bond whose issuer has the contractual right to repay it before maturity, normally under specified conditions.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b9bf235a6030b8bd2c2df6', 'Callable certificate of deposit', ARRAY[]::text[], 'A deposit product that the issuing bank may redeem early under its terms, potentially leaving the saver to reinvest at a lower rate.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_adf81eac1eacc332b37aea', 'Cash settlement', ARRAY[]::text[], 'The completion of a transaction through the transfer of money rather than physical delivery of an asset alone.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_196dfd59f16117f9093db3', 'Categorical variable', ARRAY[]::text[], 'A characteristic recorded as a class or label, such as industry, region or employment status, rather than a continuously measured quantity.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_806d94e62a39484573ce82', 'Central bank balance sheet', ARRAY[]::text[], 'The statement of a monetary authority''s assets, such as securities and lending, and liabilities, such as bank reserves and currency.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_32bf1f9f23dd8550f6173d', 'Central bank collateral framework', ARRAY[]::text[], 'The rules specifying which assets a central bank accepts as security against loans and how it values and discounts them.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_fb3a31e2fe183403ab4b71', 'Central bank refinancing operation', ARRAY[]::text[], 'A transaction through which a central bank provides funds to eligible institutions against collateral for a specified period.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_a89841740b8556b9e0819b', 'Cereal yield', ARRAY[]::text[], 'The quantity of cereal grain harvested per unit area, usually expressed in kilograms per hectare.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d25eeeb0e1a7d2522561af', 'Chained Consumer Price Index', ARRAY[]::text[], 'A US consumer price index that updates spending weights more frequently to reflect consumers'' substitution between products as prices change.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4211239967d1884001360d', 'Chi-square test of independence', ARRAY[]::text[], 'A test assessing whether two categorical variables are associated by comparing observed and expected cell frequencies in a contingency table.', 'https://openstax.org/books/introductory-statistics-2e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_13b06aa4aec34df45bf18f', 'Civilian labour force', ARRAY[]::text[], 'People classified as employed or unemployed within the civilian population, excluding those outside the labour force.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_2f7214de33881201d34cfa', 'Civilian noninstitutional population', ARRAY[]::text[], 'People above a specified minimum age who are not active-duty military personnel or residents of institutions, forming the base of many US labour surveys.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_74696e3a6d1081253957fb', 'Clearing member', ARRAY[]::text[], 'A financial institution that participates directly in a clearing house or central counterparty and is responsible for specified trades.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_679857b59275970e13b1af', 'Clearing of financial transactions', ARRAY[]::text[], 'The process of transmitting, reconciling and confirming payment or securities obligations before final settlement.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d292cb71ae2f35b25a9d10', 'Closed-end fund', ARRAY[]::text[], 'An investment company with a generally fixed number of shares traded on an exchange, where share prices can differ from the fund''s net asset value.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0f129dd43bbc8808306965', 'CO2 emissions per capita', ARRAY[]::text[], 'A country''s carbon dioxide emissions divided by its population, subject to the emissions sources included in the measure.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ef73faf7f1c05e614e62da', 'CO2 emissions per unit of GDP', ARRAY[]::text[], 'Carbon dioxide emissions relative to the value of economic production, indicating emissions intensity rather than total emissions.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_5f3af802fc390ae819751e', 'Collateral eligibility', ARRAY[]::text[], 'The conditions an asset must meet to be accepted as security in a lending or central-bank operation.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4a5bc5b780d236518471d2', 'Collateral haircut', ARRAY[]::text[], 'A reduction applied to an asset''s market value when calculating how much financing it can secure, protecting the lender against price risk.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_74a33157470b6f367b570a', 'Collective investment scheme', ARRAY[]::text[], 'An arrangement pooling investors'' contributions into a portfolio managed according to a shared investment policy.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_48b0fd072f9aac2d27353c', 'Conditional independence', ARRAY[]::text[], 'A relationship in which two events or variables are independent once a third variable or set of conditions is held fixed.', 'https://openstax.org/books/introductory-statistics-2e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_dc2fb8ab636ac8030f3802', 'Conditional probability', ARRAY[]::text[], 'The probability of an event given that another event has occurred, which need not equal its unconditional probability.', 'https://openstax.org/books/introductory-statistics-2e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_cc8c103641fc24ca4ed498', 'Consumer Expenditure Survey', ARRAY[]::text[], 'A US household survey measuring how consumers allocate spending across goods and services and providing information used in price indices.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_6093ea97417238f87b1aaa', 'Consumer Price Index for Urban Consumers', ARRAY[]::text[], 'A US measure of consumer price changes based on purchases by urban households, covering a broad population group.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0a335644da398c7da5ffa9', 'Consumer Price Index for Urban Wage Earners', ARRAY[]::text[], 'A US price index based on spending patterns of households meeting specified wage-earner and clerical-worker criteria.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d1833bac2868889379afd1', 'Contingency table', ARRAY[]::text[], 'A table cross-classifying observations by categories of two or more variables to reveal patterns of association.', 'https://openstax.org/books/introductory-statistics-2e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_88b9307cade81bbd3a2f3c', 'Contingent deferred sales charge', ARRAY[]::text[], 'A fee deducted when certain fund shares are redeemed, often depending on the length of time they were held.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_2f4026ba17434a0538a7c8', 'Continuous random variable', ARRAY[]::text[], 'A variable that can take values along an interval, such as income or time, within the precision of measurement.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_07201272341445b5274b2c', 'Cost per hour worked', ARRAY[]::text[], 'Employer spending on employee pay and benefits divided by total working hours, measuring labour compensation costs per hour.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b882a252bf319de81764be', 'Cost-of-living index', ARRAY[]::text[], 'A conceptual measure of how much spending is needed at different times to achieve the same standard of living.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_eeaf2997f4e60401088299', 'Coverage error in surveys', ARRAY[]::text[], 'A statistical problem arising when a sampling frame omits some people or includes inappropriate units relative to the intended population.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e59ab6c63dde89e5163a6c', 'Covered employment', ARRAY[]::text[], 'Jobs or workers included within a specified administrative or statistical reporting programme, such as unemployment insurance records.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_bef21a4a3c6512455b4c8c', 'Creation unit of an ETF', ARRAY[]::text[], 'A large block of ETF shares exchanged between a fund and authorised participants in the creation and redemption process.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7ce759576623a20db820b5', 'Credit institution', ARRAY[]::text[], 'A business legally authorised to take certain deposits or other repayable funds and grant credit on its own account.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4bc21011301ff7f441b2ba', 'Credit line', ARRAY[]::text[], 'A commitment allowing a borrower to draw funds up to an agreed limit, subject to the conditions of the lending contract.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4e95e315444a26f6c224dd', 'Cross-border payment', ARRAY[]::text[], 'A transfer of funds between parties located or maintaining relevant accounts in different countries, potentially involving currency conversion.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_2c35ca42432819d22ae9eb', 'Cumulative days idle', ARRAY[]::text[], 'The total number of working days lost in a labour stoppage, aggregated across affected workers during the period.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b00c3d2c1a536d709956dc', 'Cumulative distribution function', ARRAY[]::text[], 'A function giving the probability that a random variable is less than or equal to any specified value.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_da8db8644e5b2321bbc24b', 'Cumulative relative frequency', ARRAY[]::text[], 'The proportion of observations at or below a specified value or class boundary when data are arranged in order.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_28b91d94192e62f0255f6e', 'Currency in circulation', ARRAY[]::text[], 'Notes and coins issued by monetary authorities and held outside the issuing central bank, measured according to a specified definition.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_831baef0c2af771eef9108', 'Currency risk in investing', ARRAY[]::text[], 'The risk that exchange-rate movements change the home-currency value of a foreign investment or its cash flows.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b91b502cfa4ae74028ac94', 'Currency substitution', ARRAY[]::text[], 'The use of foreign money to make payments or store value in place of, or alongside, a domestic currency.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_664e77733e3d6318e3a814', 'Current Population Survey', ARRAY[]::text[], 'A monthly US household survey that produces official estimates of employment, unemployment and related labour-market conditions.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_24394d0b86c05fd99475d7', 'Current-dollar earnings', ARRAY[]::text[], 'Pay measured in the money value of the period when it was received, without adjusting for inflation.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4be5f6d0154d91fd88ceb9', 'Custodial account', ARRAY[]::text[], 'An account in which an authorised custodian holds assets on behalf of another owner or beneficiary.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_998111c3d4126b02e24e36', 'Custodian bank', ARRAY[]::text[], 'A financial institution that safeguards investors'' securities and other assets and carries out settlement and administrative services.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_af7e522b4439ee209d2484', 'Custody of securities', ARRAY[]::text[], 'The safekeeping and administration of financial instruments on behalf of owners, including servicing income and corporate actions.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_addd34bf004817718e1713', 'Debt security', ARRAY[]::text[], 'A tradable instrument representing an obligation to repay borrowed funds, usually with defined interest and principal terms.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_88b978e6a7105825cd95a2', 'Decile', ARRAY[]::text[], 'One of the cut points dividing a ranked distribution into ten portions containing roughly equal shares of observations.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_500fce749bac3222531458', 'Deferred annuity', ARRAY[]::text[], 'An annuity contract in which payments to the recipient begin after a future date rather than immediately.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_2601bd65dce29f043bd74f', 'Degrees of freedom', ARRAY[]::text[], 'The number of independent pieces of information available for estimating a statistical parameter after accounting for constraints.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_cfe9be090cad8a71fa63f3', 'Deposit facility', ARRAY[]::text[], 'A standing central-bank facility allowing eligible counterparties to place overnight funds with the monetary authority at a specified rate.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ad0a2b8d19e7e4170c3859', 'Deposit facility rate', ARRAY[]::text[], 'The interest rate a central bank pays on eligible overnight funds placed in its deposit facility, influencing short-term market rates.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0f23883e98663237be8783', 'Deposit-taking institution', ARRAY[]::text[], 'An organisation authorised to accept repayable balances from customers and provide related banking services.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d383e1c41a92a1dd2c860b', 'Direct debit', ARRAY[]::text[], 'A payment method in which a payee collects funds from a payer''s account under a prior authorisation and applicable scheme rules.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_fd9a8de4ac5fd897d17120', 'Discrete random variable', ARRAY[]::text[], 'A numerical variable whose possible outcomes form a finite or countably infinite set, such as a number of job offers received.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8c85bc5bae12923384ab81', 'Displaced worker', ARRAY[]::text[], 'Someone who loses a job for reasons such as a plant closing, an employer restructuring or the elimination of a position.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9a8c389ec72fe92a542c7e', 'Distributed payment ledger', ARRAY[]::text[], 'A shared record of payment transactions replicated across multiple participants using a coordinated validation mechanism.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0e9c7de06271cff14eb819', 'Distribution fee', ARRAY[]::text[], 'A fund charge used to finance marketing, selling or servicing fund shares, subject to the relevant regulatory rules.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8f836cdf91373fba5a28f2', 'Distribution skewness', ARRAY[]::text[], 'The extent and direction of asymmetry in a distribution, such as a long tail towards unusually high incomes.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d9e40f5109b6c3466f733f', 'Diversification benefit', ARRAY[]::text[], 'A reduction in portfolio risk gained by holding investments whose returns are not perfectly correlated.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_22f9c30428f259fe115786', 'Domestic credit to private sector', ARRAY[]::text[], 'Financing supplied by financial institutions to private businesses and households, including loans and certain other claims.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d9c0e2f35f0e7f4996a40f', 'Domestic workers', ARRAY[]::text[], 'People employed to perform services in private households, such as cleaning, caring or cooking, under the relevant occupational definition.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e8461a17ed0ff656bb311d', 'Double-blind experiment', ARRAY[]::text[], 'A study in which neither participants nor specified researchers assessing them know who receives which treatment until the relevant stage.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1705edd6ee62d217b6fa08', 'Dual-class share structure', ARRAY[]::text[], 'An arrangement where a company issues different share classes with unequal voting rights or economic entitlements.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f5cbfaafba00f4a590abe9', 'Durable manufacturing sector', ARRAY[]::text[], 'Manufacturers of goods expected to last for several years, including vehicles, machinery and household appliances.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_503bba239c84219db341f4', 'Earnings dispersion', ARRAY[]::text[], 'The degree to which pay differs across workers or jobs, often summarised using percentile ratios or measures of inequality.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0db8cab3426bfa58872018', 'Effective annual yield', ARRAY[]::text[], 'An annualised return that incorporates compounding according to a stated convention, facilitating comparison of different interest-payment frequencies.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b948d734ceb7730ab119ef', 'Eligible collateral', ARRAY[]::text[], 'Securities or other assets meeting rules for use as security against funding from a lender or central bank.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_638e5485bf1a8e23bc9132', 'Employee benefits', ARRAY[]::text[], 'Non-wage forms of employer-provided compensation, such as paid leave, insurance and retirement contributions.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_845ca3cd20764159e17dea', 'Employer compensation costs', ARRAY[]::text[], 'The combined employer expense of wages, salaries and employee benefits for a defined group of workers.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b8a510ad36d6d724e40c9d', 'Employment Cost Index', ARRAY[]::text[], 'An index tracking changes in employer labour costs over time while controlling for shifts in the occupational and industrial composition of jobs.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3d0db36cf3974893897bd4', 'Employment in agriculture', ARRAY[]::text[], 'The proportion of employed people working in agriculture, forestry and fishing according to occupational or industry classifications.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c902c1290126bcc95123cc', 'Employment in industry', ARRAY[]::text[], 'The share of employed people working in manufacturing, mining, construction, utilities and related industrial activities.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9a47b8bf4f4c032565cbfc', 'Employment in services', ARRAY[]::text[], 'The proportion of employed people whose jobs are in services-producing industries, using the relevant classification.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f879006857a5795875b56a', 'Energy intensity of GDP', ARRAY[]::text[], 'The quantity of energy used per unit of economic output, often calculated using purchasing-power-adjusted GDP.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_a7f03af7179b3893a43df2', 'Escrow account', ARRAY[]::text[], 'An account in which a third party holds funds or assets until specified contractual conditions are fulfilled.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3f30036f613fe4d23c28a5', 'Establishment survey', ARRAY[]::text[], 'A survey of employers or workplaces used to estimate measures such as payroll jobs, hours and earnings.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c101989abbc889fcfb4f77', 'Estimator bias', ARRAY[]::text[], 'The difference between an estimator''s expected value across repeated samples and the population parameter it aims to estimate.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_bbfe1e3033dac63403b815', 'Estimator consistency', ARRAY[]::text[], 'The property that an estimator approaches the true parameter as the amount of appropriate sample information grows.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3df903348b4bbc054330d6', 'Euro short-term rate', ARRAY[]::text[], 'An ECB benchmark measuring wholesale unsecured overnight borrowing costs of banks in euros, based on reported transactions.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_30ea60b5b33b2cfe77e633', 'Eurosystem', ARRAY[]::text[], 'The European Central Bank together with the national central banks of countries that use the euro.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c735cf42d41c1d00fb5115', 'Eurozone payment settlement', ARRAY[]::text[], 'The transfer and final discharge of euro-denominated payment obligations through the relevant banking and payment infrastructure.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b5462966f9bc57b1342b16', 'Event complement', ARRAY[]::text[], 'The set of all possible outcomes in which a specified event does not occur.', 'https://openstax.org/books/introductory-statistics-2e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_741a3015f506b77193eed9', 'Ex-dividend date', ARRAY[]::text[], 'The date from which a security trades without entitlement to a previously announced dividend for a new buyer, under settlement rules.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e2865ccb43283357ee2c46', 'Exchange-listed security', ARRAY[]::text[], 'A security admitted to trading on a regulated or organised stock exchange, subject to its listing rules.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9d43b6137891855a9d4971', 'Exchange-traded note', ARRAY[]::text[], 'An unsecured debt instrument whose return tracks an index or benchmark, exposing investors to the issuer''s credit risk.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7da3808fc1a939e8185610', 'Expected value of a random variable', ARRAY[]::text[], 'The probability-weighted mean of a random variable''s possible outcomes, interpreted as its long-run average over repeated trials.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4b2e2f083285183ce2905d', 'Expected years of schooling', ARRAY[]::text[], 'The number of years a child of school-entry age could expect to spend enrolled in education if current participation patterns persist.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b5fac080f015086f637502', 'Expense ratio', ARRAY[]::text[], 'A fund''s annual operating expenses expressed as a percentage of its average net assets, reducing investors'' net returns.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_882ab4ab2c54b92d78a768', 'Exponential distribution', ARRAY[]::text[], 'A continuous distribution often used to describe waiting times between independent events in a constant-rate Poisson process.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_54ff43bb2cc66626ef9482', 'Fair value of an investment', ARRAY[]::text[], 'An estimate of the amount at which an asset or liability could be exchanged in an orderly market transaction under applicable valuation rules.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_96b7afa2d8b50a584fa1b3', 'Fatal occupational injury', ARRAY[]::text[], 'A death caused by an event or exposure occurring in the course of work, as counted under workplace injury reporting rules.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_dff21384a1d6a27984e4b2', 'Financial adviser', ARRAY[]::text[], 'A professional who provides guidance or recommendations about financial planning or investments, under applicable licensing and conduct rules.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_98fcd13daaaeb8c8d4bc14', 'First quartile', ARRAY[]::text[], 'The value marking approximately the 25th percentile of ordered observations, below which about a quarter of the data lie.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_90d3891bfbaf89232f12e3', 'Fitted regression value', ARRAY[]::text[], 'The value predicted for an observation by a regression equation using estimated coefficients and its explanatory variables.', 'https://openstax.org/books/introductory-statistics-2e/pages/12-3-the-regression-equation', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_32855a7906ed745ebc7169', 'Fixed annuity', ARRAY[]::text[], 'An insurance contract promising specified interest or income payments according to the insurer''s contractual obligations.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_04daac0e8df529cb4410b6', 'Fixed-rate bond', ARRAY[]::text[], 'A bond paying interest at a contractual rate that does not change over its life, unless the instrument has special terms.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_06338d71670359c67be7c0', 'Flexible working schedule', ARRAY[]::text[], 'An employment arrangement permitting workers to vary some aspects of their working time within employer or legal constraints.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d59e0f4f661c3a507faac6', 'Foreign exchange swap', ARRAY[]::text[], 'A transaction exchanging two currencies at an agreed spot rate with a simultaneous commitment to reverse the exchange at a future date.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1e37716d06ce8b3d559e56', 'Forest area share', ARRAY[]::text[], 'The proportion of a country''s land area classified as forest according to the relevant international statistical standard.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8301111330b047564b7ae1', 'Frequency distribution', ARRAY[]::text[], 'A summary of how many observations take each category or fall within each numerical interval.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0650e9c78d4b9d88384e57', 'Frequency polygon', ARRAY[]::text[], 'A line graph joining the frequencies or relative frequencies of successive numerical class intervals.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_5318152fc5d34567f79b09', 'Freshwater withdrawal rate', ARRAY[]::text[], 'The volume of freshwater withdrawn for domestic, agricultural or industrial use over a period, sometimes expressed relative to available resources.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e6b42f792fcdf1d51948eb', 'Front-end sales load', ARRAY[]::text[], 'An investment fund sales fee deducted when shares are purchased, reducing the amount initially invested.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_eddb0de5698f41b3ba2523', 'Full-time employment status', ARRAY[]::text[], 'A classification of workers based on hours usually worked, with the threshold dependent on the statistical survey or employer.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_54e3012abbab83f904f30d', 'Fund family', ARRAY[]::text[], 'A group of investment funds managed or distributed by the same organisation, often sharing branding and administrative services.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_230945055020b092d6cca2', 'Fund of funds', ARRAY[]::text[], 'A pooled investment vehicle whose portfolio consists mainly of holdings in other investment funds.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ae46ce24abac729d7df4bc', 'Future value', ARRAY[]::text[], 'The amount an asset or sum is expected to be worth at a specified future time after assumed growth or interest.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c6a1aa0bc7a08292cd08e9', 'Futures contract', ARRAY[]::text[], 'A standardised agreement to buy or sell a specified asset at a future date at a price established in a traded contract.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_97e3aa874be659cd54974d', 'General obligation municipal bond', ARRAY[]::text[], 'A local-government bond backed by the issuer''s broad taxing power rather than solely by revenue from a named project.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_407a087887ca12949bc0d1', 'Geometric distribution', ARRAY[]::text[], 'The probability distribution of the number of independent Bernoulli trials required to obtain the first success.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9d82dda9a2492837d8fbe7', 'Geometric mean', ARRAY[]::text[], 'An average obtained from the product of positive values, useful for compounding growth rates or comparing multiplicative changes.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_68ec37d99481f5a697ad09', 'Goodness-of-fit test', ARRAY[]::text[], 'A procedure comparing observed frequencies or outcomes with those predicted by a particular statistical distribution or model.', 'https://openstax.org/books/introductory-statistics-2e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3e488fe91079e3fa9a7be7', 'Government education spending share', ARRAY[]::text[], 'Public expenditure on education expressed as a share of a country''s total government spending or GDP, depending on the specified indicator.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e7e2980a99c46710f8ea35', 'Gross job gains', ARRAY[]::text[], 'Total employment increases at expanding establishments plus jobs added by newly opening establishments during a period.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3d2ae211559be85cfd723c', 'Gross job losses', ARRAY[]::text[], 'Total employment reductions at contracting establishments plus jobs lost when establishments close during a period.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_59b087573e8cf3fff80b2f', 'Gross national income', ARRAY[]::text[], 'The total income earned by an economy''s residents from domestic and foreign sources, including net primary income received from abroad.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_34ff9879569be53b576dd8', 'Gross national income per capita', ARRAY[]::text[], 'Gross national income divided by the population, often converted to a common currency to compare average income across countries.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_57e0384f694e0c9f7938b4', 'Gross school enrolment ratio', ARRAY[]::text[], 'The number enrolled at a given education level, regardless of age, divided by the population of the official age group for that level.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1c301a6f3c954c263aa290', 'Growth fund', ARRAY[]::text[], 'An investment fund focusing on companies expected to grow earnings or revenue relatively quickly, often with less emphasis on current dividends.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ddc6ada34fb290e388fcf5', 'High-frequency payment settlement', ARRAY[]::text[], 'The continuous processing of many payment instructions within a system designed for rapid settlement.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_bdfb01f3ea1f6351d0d53d', 'Histogram', ARRAY[]::text[], 'A chart representing the frequency or density of observations in numeric intervals using adjacent bars.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_529b39303235d3bc84267d', 'Hours at work', ARRAY[]::text[], 'The hours actually worked during a reference period, excluding absences such as holidays or sickness even if paid.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_99e2595c476fda8cee82d8', 'Household employment survey', ARRAY[]::text[], 'A survey asking individuals about work and job search, including self-employment and multiple-job holding, rather than relying only on employer payroll records.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_23abd8d1b64209e5f1cdf3', 'Household reference person', ARRAY[]::text[], 'The individual designated as the principal reference in a household survey for organising household and family information.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_38634393844eb803b8bea5', 'Human Capital Index', ARRAY[]::text[], 'A World Bank indicator estimating the productivity a child born today can expect to achieve based on education and health conditions.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b1d08372a3e252fc46087a', 'Import price index', ARRAY[]::text[], 'An index measuring changes in prices of goods and selected services purchased from abroad, according to the index''s coverage.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3b2017ab510c46bb06be39', 'Income fund', ARRAY[]::text[], 'An investment fund seeking regular distributions from assets such as bonds, dividend-paying shares or property.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_13f3e79376cdfa353e8b78', 'Income share of the poorest quintile', ARRAY[]::text[], 'The percentage of total income or consumption received by the lowest-income fifth of a population.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_5057028ea10f294d68a422', 'Income share of the richest decile', ARRAY[]::text[], 'The percentage of total income or consumption received by the highest-income tenth of a population.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_772bb2ce78f4edd7052a4e', 'Independent events', ARRAY[]::text[], 'Events for which learning that one occurred does not change the probability of the other occurring.', 'https://openstax.org/books/introductory-statistics-2e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_012b5a5141635b26c2833a', 'Industrial injury incidence rate', ARRAY[]::text[], 'The number of work-related injuries or illnesses relative to a measure of labour exposure, such as hours worked.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_6a40dc62356316f04e2385', 'Industry employment', ARRAY[]::text[], 'The number of workers or jobs in an industry defined by a standard classification system.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_05ce713bb04e6cfeae8ea3', 'Infant mortality rate', ARRAY[]::text[], 'The probability of death before a child''s first birthday, generally expressed per 1,000 live births.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f1b65099ef70f8205087f0', 'Interbank lending market', ARRAY[]::text[], 'A market in which banks lend funds to and borrow funds from one another, commonly over short maturities.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_744b773587203deb5084dc', 'Interbank liquidity', ARRAY[]::text[], 'Funds available to banks for payments and financing, including central-bank reserves and borrowings from other banks.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b101644c1cf064048da2e9', 'International Bank Account Number', ARRAY[]::text[], 'A standardised identifier for bank accounts designed to improve the routing and accuracy of cross-border payments.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_841133526789f9e015cb00', 'International central securities depository', ARRAY[]::text[], 'A securities depository providing custody and settlement services across national markets or multiple currencies.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c0676093f0828ed4c66ffb', 'International poverty line', ARRAY[]::text[], 'A standard purchasing-power-adjusted monetary threshold used to compare the incidence of extreme poverty across countries.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_65036fed2e94b747274159', 'Interquartile range', ARRAY[]::text[], 'The distance between the 75th and 25th percentiles of a distribution, measuring the spread of its central half.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_21ecde0fb2ef5718d056e9', 'Interval estimate', ARRAY[]::text[], 'A range constructed from data to provide information about the plausible values of an unknown population parameter.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ce0e45ee6f49a1d86a32ad', 'Investment company', ARRAY[]::text[], 'An organisation that pools capital from investors to buy a portfolio of securities, subject to the applicable fund structure and regulation.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_bdd8f84a8774fee93ff7f4', 'Investment objective', ARRAY[]::text[], 'A stated aim for an investment portfolio, such as capital growth, income generation or preservation of invested capital.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_a03bcd9e723717be30f47c', 'Investment prospectus', ARRAY[]::text[], 'A formal disclosure document describing an investment offering''s objectives, risks, costs and other material information.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_903cc30388e76a91092985', 'Investor protection', ARRAY[]::text[], 'Legal, regulatory and market safeguards intended to promote fair dealing, disclosure and the proper handling of investors'' assets.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_32f59c2853348ef976edc8', 'Issuer in payment cards', ARRAY[]::text[], 'A bank or other institution that issues cards to customers and authorises or settles relevant payment obligations.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b3758202dd6bb46f8fce64', 'Job opening', ARRAY[]::text[], 'An unfilled position for which work is available and the employer is actively recruiting under the survey''s criteria.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b19330ef518cf5cb9221bd', 'Job openings rate', ARRAY[]::text[], 'Unfilled positions expressed as a percentage of total positions, including both occupied jobs and vacancies, at a reference date.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d0ceeb216a73b02a385c6a', 'Job tenure', ARRAY[]::text[], 'The length of time an employee has worked for their current employer, which can signal job stability.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_cc59a84c36dad47065744a', 'Job-to-job transition', ARRAY[]::text[], 'A worker''s movement directly between employers without an intervening recorded period of unemployment.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7c23105edd2ddd4aba6329', 'Joint probability', ARRAY[]::text[], 'The probability that two specified events both occur, often written as the probability of A and B.', 'https://openstax.org/books/introductory-statistics-2e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_6516f8cd6e54a3add402b4', 'Labour compensation', ARRAY[]::text[], 'The combined value of wages, salaries and employer-paid benefits received by workers for their services.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_2d59ec30aeb610fa65dfeb', 'Labour composition effect', ARRAY[]::text[], 'The contribution of changes in the measured characteristics of workers, such as education or experience, to productivity growth.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_47965330440405fc237b9a', 'Labour turnover', ARRAY[]::text[], 'The movement of workers into and out of jobs, including hires, voluntary quits, layoffs and other separations.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8764e61ce7a4ab95fa13df', 'Large-cap equity', ARRAY[]::text[], 'Shares in a company with a relatively large market value, with the size threshold depending on the market or index provider.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9522ac387e7495cbca4c72', 'Large-value payment system', ARRAY[]::text[], 'A payment infrastructure designed to transfer and settle substantial or time-critical payments, often between financial institutions.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b7c5538cc0a8e7cdff3344', 'Law of total probability', ARRAY[]::text[], 'A rule expressing an event''s probability as the weighted sum of its conditional probabilities across mutually exclusive cases.', 'https://openstax.org/books/introductory-statistics-2e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_59703266dcf522e96afff8', 'Layoffs and discharges', ARRAY[]::text[], 'Employer-initiated separations from work, including redundancies and dismissals, excluding voluntary resignations.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9fa6ccfb3359cd8c1ef1cd', 'Learning-adjusted years of schooling', ARRAY[]::text[], 'A measure combining the expected duration of education with learning outcomes to approximate effective years of schooling.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f56919a41fd43c40b35ac3', 'Least-squares estimation', ARRAY[]::text[], 'A method choosing regression coefficients to minimise the sum of squared differences between observed and fitted outcomes.', 'https://openstax.org/books/introductory-statistics-2e/pages/12-3-the-regression-equation', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e5560c3d71886bba641ad0', 'Life expectancy at birth', ARRAY[]::text[], 'The average years a newborn would live if current age-specific mortality rates remained unchanged throughout their life.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ffb994058237318ddd8d30', 'Liquidity provision operation', ARRAY[]::text[], 'Central-bank action supplying funds or reserves to eligible financial institutions, usually through lending or asset purchases.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_dd145512beff38c5d16003', 'Liquidity-absorbing operation', ARRAY[]::text[], 'Central-bank action designed to reduce excess reserve balances or short-term liquidity in the banking system.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_01c1b1eef2abc13eeec389', 'Load fund', ARRAY[]::text[], 'A mutual fund that charges a sales commission when investors buy or redeem shares.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3967e6dcf9dae106383605', 'Long-term unemployment', ARRAY[]::text[], 'Unemployment lasting beyond a specified duration threshold, commonly 27 weeks or more in US statistics.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_5999ec038f3be996e19cfc', 'Longer-term refinancing operation', ARRAY[]::text[], 'A Eurosystem lending operation providing funds to eligible banks for maturities beyond ordinary short-term refinancing operations.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_6e392c8c600ad2927d258c', 'Main refinancing operations', ARRAY[]::text[], 'Regular Eurosystem transactions that supply eligible institutions with central-bank liquidity for short maturities.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3c7f6bea7bba33ea69b6aa', 'Manufacturing value added', ARRAY[]::text[], 'The contribution of manufacturing activities to gross domestic product, excluding the cost of intermediate goods and services.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9f0bde2c3c072f82804f56', 'Margin of error', ARRAY[]::text[], 'A quantity expressing the estimated sampling uncertainty on either side of a point estimate at a stated confidence level.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_271361526958386675cab8', 'Marginal lending facility', ARRAY[]::text[], 'A standing central-bank facility allowing eligible counterparties to obtain overnight credit against collateral at a specified rate.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e7c1f47ac5cd7798015303', 'Market infrastructure oversight', ARRAY[]::text[], 'The monitoring of payment, clearing or settlement systems to ensure their safety, resilience and efficient operation.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8f3cd02c67ac6e4abd9167', 'Market timing strategy', ARRAY[]::text[], 'An attempt to change investment exposure by forecasting when market prices will rise or fall, rather than remaining consistently invested.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_a1201b2acf8996de5fe769', 'Maternal mortality ratio', ARRAY[]::text[], 'Maternal deaths related to pregnancy or its management per 100,000 live births in a specified period.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_a7551b4e354cc25676eefb', 'Minimum investment requirement', ARRAY[]::text[], 'The smallest contribution an investor must make to purchase or maintain a particular investment product.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0285699b6637fc06e68a1f', 'Minimum reserve system', ARRAY[]::text[], 'A central-bank framework requiring eligible financial institutions to maintain specified reserve balances under defined averaging and calculation rules.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_2d6f2fd70548f1f394536d', 'Monetary policy corridor', ARRAY[]::text[], 'The range between central-bank standing facility rates that can influence the overnight interbank interest rate.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ba01479745d1a55714f31f', 'Monetary policy implementation', ARRAY[]::text[], 'The operational transactions and rules used by a central bank to bring market funding conditions into line with its policy decisions.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f8b9430d62dc428710c2c9', 'Multidimensional poverty index', ARRAY[]::text[], 'An indicator of poverty based on several disadvantages, such as health, education and living standards, rather than monetary resources alone.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d282de68c81890a0670cb4', 'Multilateral netting', ARRAY[]::text[], 'The offsetting of obligations between multiple parties so that each participant settles a single net position rather than each gross payment.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_779ab5bfa321b051e2dea9', 'Multiple jobholding', ARRAY[]::text[], 'Working in more than one job during the survey reference period, which can make job counts exceed the number of employed people.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_47a077642dd0a74487c6b5', 'Mutually exclusive events', ARRAY[]::text[], 'Events that cannot both occur in the same trial, so the probability of their intersection is zero.', 'https://openstax.org/books/introductory-statistics-2e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_cf62dba873adc6a724d5aa', 'National poverty threshold', ARRAY[]::text[], 'An income or consumption benchmark set within a country to identify people who cannot meet its defined minimum living standard.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_307550857f450ed5e61a33', 'Neonatal mortality rate', ARRAY[]::text[], 'The probability of death during the first 28 days after birth, commonly expressed per 1,000 live births.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_de03195b456f1775c6909f', 'Net employment change', ARRAY[]::text[], 'The difference between jobs gained and jobs lost over a period, reflecting expansion, contraction, openings and closures.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_00f1575abdd24cd5dbcd16', 'Net expense ratio', ARRAY[]::text[], 'The fund operating-expense ratio after contractual waivers or reimbursements, which may cease under specified conditions.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e0c8f30ccdde2ea913f08f', 'Net migration rate', ARRAY[]::text[], 'The balance of people entering and leaving a country over a period, commonly expressed relative to its population.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1f617a30291dab9c9390b2', 'Net school enrolment rate', ARRAY[]::text[], 'The percentage of children of the official age group for an education level who are enrolled at that level.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_167e3f2efba0c25f0ed704', 'Net settlement system', ARRAY[]::text[], 'A payment system in which participants settle obligations calculated after offsetting incoming and outgoing payments.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4d31d51c2fdf05d7b6a6ba', 'Newly opened establishment', ARRAY[]::text[], 'A workplace newly identified as operating during the relevant statistical period, potentially creating additional jobs.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ee9eb68b8f9e1e00b94caa', 'No-action letter', ARRAY[]::text[], 'A regulatory staff communication indicating that the agency''s staff would not recommend enforcement for a described course of conduct under specified facts.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c89fa897b3d30c83138e25', 'No-load fund', ARRAY[]::text[], 'A mutual fund without a front-end or deferred sales load, although it may still impose other expenses.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d35e5dafe8971f3f2e1b7d', 'Non-durable goods manufacturing', ARRAY[]::text[], 'Production of goods normally used or consumed relatively quickly, such as food, paper and certain chemicals.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e6d857c9a2c3f592b81621', 'Non-probability sampling', ARRAY[]::text[], 'A method of selecting observations without known selection probabilities, limiting the kinds of statistical inference that can be justified.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f86da67502741085062c21', 'Non-sampling error', ARRAY[]::text[], 'Error caused by problems such as inaccurate measurement, missing responses or recording mistakes rather than the selection of a sample.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_969d3c05bb2ca9d54800c0', 'Nonfarm payroll employment', ARRAY[]::text[], 'A US measure of jobs on the payrolls of most non-agricultural employers, excluding categories such as self-employed workers.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9718f219f100ae721215e8', 'Normal approximation', ARRAY[]::text[], 'The use of a normal distribution to approximate another sampling distribution when suitable sample-size and regularity conditions hold.', 'https://openstax.org/books/introductory-statistics-2e/pages/6-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_fe10ad0f63932457c6368f', 'Observation unit', ARRAY[]::text[], 'The entity on which a variable is measured in a dataset, such as an individual, household, firm or country.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b275a313402db4ca53facf', 'Occupational classification', ARRAY[]::text[], 'A system for grouping jobs by the tasks, duties and skills generally required, rather than by the employer''s industry.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_771b6b541ba43ee189f614', 'Occupational Employment and Wage Statistics', ARRAY[]::text[], 'A US statistical programme estimating employment and pay for occupations across industries and geographic areas.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d12650047f79dc60f8e1ed', 'Occupational injury severity', ARRAY[]::text[], 'A measure of how seriously an injury affects a worker, for example through days away from work or restricted duties.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_369d94e6d085ed07654669', 'Occupational requirement', ARRAY[]::text[], 'A skill, physical activity or other demand associated with performing a particular type of job.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_283588d54668c0bcee53c8', 'Old-age dependency ratio', ARRAY[]::text[], 'The number of people above a specified older-age threshold relative to those of working age.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d5cb99104b14c493072f29', 'One-sided hypothesis test', ARRAY[]::text[], 'A statistical test designed to detect a departure from a null value in one specified direction only.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ffd6c431c26148bd67744e', 'Option exercise price', ARRAY[]::text[], 'The fixed price at which an option holder may buy or sell the underlying asset when exercising the contract.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f6cbb3ce406db565d584f5', 'Option expiration date', ARRAY[]::text[], 'The date after which an options contract can no longer be exercised under its terms.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0d108a5309a625ea979cd0', 'Option premium', ARRAY[]::text[], 'The price paid by the buyer of an option to obtain the contractual right it provides, which the seller receives in exchange for taking an obligation.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c545cd15df9212b573148f', 'Ordinal variable', ARRAY[]::text[], 'A categorical characteristic whose levels have a meaningful order but not necessarily equal numerical gaps between them.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_2e447a13577497cd59c7dd', 'Outlier observation', ARRAY[]::text[], 'A data point lying unusually far from the bulk of observed values, potentially reflecting a genuine event or a measurement problem.', 'https://openstax.org/books/introductory-statistics-2e/pages/12-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1831d6fd80b9dac8038dd3', 'Output per hour worked', ARRAY[]::text[], 'A labour productivity measure calculated by dividing real output by the number of labour hours used in production.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9e65fc97ae1aefdea74bfa', 'Over-the-counter security', ARRAY[]::text[], 'A security traded through dealer networks or other arrangements rather than being listed on a major exchange.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1f1d12bb2d57e6ba8fc46d', 'Overnight interest rate', ARRAY[]::text[], 'The rate charged on funds lent for one business night, often used as an indicator of short-term money-market conditions.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_15497c1afdcb0154898da6', 'Paired observations', ARRAY[]::text[], 'Measurements organised into matched pairs, such as wages for the same workers before and after a policy change.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_60ebbbeb50facb6daf4242', 'Part-time employment status', ARRAY[]::text[], 'A classification of workers whose usual hours fall below a specified threshold, which varies by survey or jurisdiction.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1fe30c7ce51ab1c3fc0b6c', 'Payment account', ARRAY[]::text[], 'An account held in the name of a customer and used to execute payment transactions under a financial institution''s rules.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_2a2f6e96fc85973110d8f7', 'Payment initiation service', ARRAY[]::text[], 'A service that initiates a transfer from a customer''s payment account at another provider with the customer''s authorisation.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d2a369b03b21b4dfd2c885', 'Payment instrument', ARRAY[]::text[], 'A card, application, instruction or agreed procedure through which a user initiates a payment transaction.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c4f8429026417589df3fef', 'Payment-versus-payment settlement', ARRAY[]::text[], 'A foreign-exchange settlement arrangement ensuring one currency is transferred only if the other currency is transferred.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_264d3ca7849417ea6e43e5', 'Payroll survey revision', ARRAY[]::text[], 'A correction to previously estimated employment or earnings figures when new employer reports or more complete data become available.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c38576fa39a61c775ac080', 'Percentile rank', ARRAY[]::text[], 'The approximate percentage of observations at or below a specified value in a distribution.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_76bf6a547afff5035ed7e1', 'Point estimate', ARRAY[]::text[], 'A single value calculated from a sample to estimate an unknown population parameter.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b3c798290ce12fc93ba1b9', 'Poisson distribution', ARRAY[]::text[], 'A discrete probability model for counts of events occurring independently at a constant average rate within an interval.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4752e27cc80670a3998351', 'Pooled proportion', ARRAY[]::text[], 'An estimate of a common population proportion obtained by combining successes and observations across comparison groups under the relevant null assumption.', 'https://openstax.org/books/introductory-statistics-2e/pages/10-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_69e46b67d898a5b7c270e5', 'Population density', ARRAY[]::text[], 'The number of residents divided by a defined land area, usually expressed as people per square kilometre.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f5853c3c250291d34aeef9', 'Population growth rate', ARRAY[]::text[], 'The percentage change in a population over a specified period, reflecting births, deaths and net migration.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7281c8e8964b35d170bf70', 'Population parameter', ARRAY[]::text[], 'A fixed but usually unknown numerical characteristic of a population, such as its mean income or unemployment share.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_33a06fc8ee8c588f98d408', 'Population variance', ARRAY[]::text[], 'The average of squared deviations from the population mean, describing dispersion across the entire population.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8505f3a8e021ea63bd1fdd', 'Portfolio turnover rate', ARRAY[]::text[], 'A measure of how frequently a fund buys and sells its holdings over a period, potentially affecting trading costs and taxes.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_68f528f3ad4b6178b03838', 'Poverty gap index', ARRAY[]::text[], 'An indicator measuring the average shortfall below the poverty line, expressed relative to that line and including non-poor people as zero shortfall.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7a56afa8cf4a72b2cb29de', 'Poverty headcount ratio', ARRAY[]::text[], 'The proportion of people whose income or consumption falls below a specified poverty line.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3b7922e5a19d47c9e6bd08', 'Prediction interval', ARRAY[]::text[], 'A range estimating where an individual future observation could fall under a model, usually wider than a confidence interval for the conditional mean.', 'https://openstax.org/books/introductory-statistics-2e/pages/12-3-the-regression-equation', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8ec609375cb731bc9dd09b', 'Preferred stock', ARRAY[]::text[], 'An equity class that may receive priority over ordinary shares for dividends or liquidation proceeds but often has limited voting rights.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_98dc3aa643e19502142f1a', 'Primary completion rate', ARRAY[]::text[], 'An indicator of the proportion of children completing the final grade of primary education, calculated under a specified statistical method.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f8479b04881c19e1ab2589', 'Private sector credit-to-GDP ratio', ARRAY[]::text[], 'Outstanding credit to households and private firms relative to annual GDP, a rough measure of financial-sector depth.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1114e170a6a8cb014c9d38', 'Probability density function', ARRAY[]::text[], 'A non-negative function whose area over a range gives the probability that a continuous random variable falls within that range.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_85aba127e834604a4a7ff6', 'Probability mass function', ARRAY[]::text[], 'A function assigning probabilities to the possible discrete values of a random variable, with total probability equal to one.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ae78001e6110a879c0334a', 'Probability sampling', ARRAY[]::text[], 'Sampling in which eligible population members have known, non-zero selection probabilities under a specified design.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c6ee428e9ddcfe11174bbd', 'Pupil-teacher ratio', ARRAY[]::text[], 'The number of enrolled students relative to the number of teachers at a given level of education.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0a7918b67ab33fc87570dd', 'Random variable', ARRAY[]::text[], 'A numerical quantity determined by the outcome of an uncertain event or experiment.', 'https://openstax.org/books/introductory-statistics-2e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_99e4aa2dc7158447fd1809', 'Range of a dataset', ARRAY[]::text[], 'The difference between the largest and smallest observed values, a simple but outlier-sensitive measure of spread.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7c9563c6d2174178a15df7', 'Real average hourly earnings', ARRAY[]::text[], 'Average hourly pay adjusted for consumer price changes to show the purchasing power of earnings over time.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ad23c1158939dca8bd4bbe', 'Real compensation per hour', ARRAY[]::text[], 'Total employee remuneration per hour worked, adjusted for inflation using an appropriate price index.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f2159df7662687189460af', 'Real-time payment', ARRAY[]::text[], 'A transfer in which funds are made available to the beneficiary within seconds or minutes under a rapid payments scheme.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_6453ee4602e5aae508a60f', 'Redemption fee', ARRAY[]::text[], 'A fee deducted when an investor sells or redeems an investment fund holding, often intended to discourage short-term trading.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1546e8cc5f68c16f91849b', 'Redenomination of currency', ARRAY[]::text[], 'Changing the monetary unit in which prices, accounts or contracts are expressed, often during a currency reform.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_6559c3ff413d1996b460c8', 'Reentrants to the labour force', ARRAY[]::text[], 'People returning to the active labour force after time outside employment and active job search.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_16a89c61e02721cbf4b9ae', 'Reference interest rate', ARRAY[]::text[], 'A published rate used as a benchmark for calculating interest payments or valuing financial contracts.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_98b98b3ec9ac451b52d65f', 'Regression forecast error', ARRAY[]::text[], 'The difference between a realised future outcome and the value predicted by a regression or forecasting model.', 'https://openstax.org/books/introductory-statistics-2e/pages/12-3-the-regression-equation', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8a74de6300ef676def1dee', 'Regression intercept', ARRAY[]::text[], 'The value predicted by a linear regression when all included explanatory variables equal zero, whether or not that case is meaningful.', 'https://openstax.org/books/introductory-statistics-2e/pages/12-1-linear-equations', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7876eb0eb1d73f0769828d', 'Regression slope coefficient', ARRAY[]::text[], 'An estimated change in the predicted outcome associated with a one-unit change in an explanatory variable, under a linear regression model.', 'https://openstax.org/books/introductory-statistics-2e/pages/12-1-linear-equations', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3027039f6b004d64bd14f4', 'Reinvestment risk', ARRAY[]::text[], 'The possibility that cash received from an investment must be reinvested at a lower rate of return than expected.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9cf15c90c7fd4ae9167e8d', 'Relative frequency', ARRAY[]::text[], 'The proportion of observations falling in a category or interval, calculated by dividing its count by the total number of observations.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_24280dddff6adcec8f7b31', 'Renewable electricity output share', ARRAY[]::text[], 'The fraction of electricity generation provided by renewable energy sources such as hydro, wind and solar.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_eb2a1d60ded86ec9833d69', 'Renewable energy consumption share', ARRAY[]::text[], 'The fraction of total final energy use supplied by renewable sources under the applicable energy-accounting methodology.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8b06a738d19bfff63140d4', 'Repurchase agreement', ARRAY[]::text[], 'A transaction in which securities are sold with an agreement to buy them back later, economically resembling secured short-term borrowing.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1227c437df531d12ee2b6a', 'Reserve maintenance period', ARRAY[]::text[], 'The interval over which banks'' reserve balances are assessed against a central bank''s minimum requirements.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e1d555896b95e896b4f8f9', 'Reserve remuneration', ARRAY[]::text[], 'Interest paid by a central bank on balances held by eligible financial institutions, under the relevant monetary framework.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7ea9f3461cf4c55ea09c71', 'Residual in regression', ARRAY[]::text[], 'The difference between an observation''s actual outcome and the corresponding value predicted by a fitted regression model.', 'https://openstax.org/books/introductory-statistics-2e/pages/12-3-the-regression-equation', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8ec6935b7e805aac9beb13', 'Response bias', ARRAY[]::text[], 'A systematic distortion in collected answers caused by how questions are asked or by respondents'' incentives, memories or expectations.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d1a505d69e231eed1b0b84', 'Retail investor', ARRAY[]::text[], 'An individual investing on their own account rather than as a professional institution or large investment organisation.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b04aaa0aaaa08f25e3e311', 'Retail payment system', ARRAY[]::text[], 'Infrastructure processing payments made by households and businesses, often with many relatively small transactions.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9d848fe1bd87975c289a90', 'Revenue bond', ARRAY[]::text[], 'A public-sector bond repaid primarily using revenues generated by a specified project, utility or facility.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_65b9d56959e4ebda8d71d9', 'Reverse repurchase agreement', ARRAY[]::text[], 'A transaction in which a party purchases securities subject to their later resale, economically resembling secured lending.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e5628e618d188d0bb191c8', 'Rights issue', ARRAY[]::text[], 'An offer of new shares to existing shareholders, usually giving them the opportunity to maintain their proportional ownership.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0b570f3a9e472b41943ebd', 'Risk control measure for collateral', ARRAY[]::text[], 'A measure such as a haircut or concentration limit that protects a lender against loss from pledged assets.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c405c0d3eec3172755703b', 'Sample median', ARRAY[]::text[], 'The middle value of a ranked sample, or the average of two middle values when the sample contains an even number of observations.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_5b0939ca3b6946a080e166', 'Sample space in probability', ARRAY[]::text[], 'The complete set of possible outcomes of a specified random experiment.', 'https://openstax.org/books/introductory-statistics-2e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_02166e06cd10261300be33', 'Sample statistic', ARRAY[]::text[], 'A numerical quantity calculated from observed data, used to describe the sample or estimate a population parameter.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ee9288571614cdbd34fc98', 'Sample variance', ARRAY[]::text[], 'A measure of dispersion based on squared deviations of observations from their sample mean, usually divided by one less than the sample size.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_273ca07b35afe3029c87ec', 'Sampling error', ARRAY[]::text[], 'The difference between a sample statistic and the corresponding population value arising because only part of the population was observed.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3efbf4c1180e9146ccd6b4', 'Sampling frame', ARRAY[]::text[], 'The operational list or mechanism from which a statistical sample is selected, which may differ from the complete population of interest.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_465081818dc9b9e26dbf6a', 'Seasonally adjusted unemployment rate', ARRAY[]::text[], 'An unemployment estimate statistically adjusted to reduce predictable seasonal patterns such as school-leaving or holiday hiring.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c165f5b3d5093e58ca5e3d', 'Securities lending', ARRAY[]::text[], 'A transaction in which securities are temporarily transferred to a borrower against collateral and an obligation to return equivalent securities.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_bdb82d9ceb1839416d3258', 'Securities settlement system', ARRAY[]::text[], 'Infrastructure that records or transfers financial securities and supports discharge of the associated ownership obligations.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d5d74b17c4f9b183c58001', 'Selection into a sample', ARRAY[]::text[], 'The process determining which units appear in a dataset; non-random inclusion can bias estimates of the wider population.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c865859e0961efa542796d', 'Self-employed worker', ARRAY[]::text[], 'A person working in their own business, professional practice or trade rather than as an employee of another employer.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_5756bb3bdda2367ca8252b', 'Separation rate', ARRAY[]::text[], 'The share of jobs ending during a period through quits, layoffs, discharges or other separations relative to total employment.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_017092dd2d20398db17869', 'Services value added', ARRAY[]::text[], 'The contribution of services industries to economic output after deducting intermediate inputs.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_30dfb13ca40399aa97449d', 'Settlement bank', ARRAY[]::text[], 'An institution through which participants in a payment or securities system settle their monetary obligations.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_cf15d9af95215aab513928', 'Settlement finality', ARRAY[]::text[], 'The legally defined point at which a payment or securities transfer becomes irrevocable and unconditional within a settlement system.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_3561578b96012127a88fd0', 'Share certificate', ARRAY[]::text[], 'A document or electronic record evidencing ownership of a specified number or class of company shares.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_13e291883b8ada0c8ba98d', 'Shared prosperity measure', ARRAY[]::text[], 'An indicator assessing growth in average income or consumption among the bottom 40% of a country''s distribution.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0f11c82abd1db6a3e467bc', 'Shift work', ARRAY[]::text[], 'An arrangement in which different groups of employees work during separate scheduled periods to maintain operations over an extended day.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d1731a6bf96683a1f7315f', 'Short-time working', ARRAY[]::text[], 'An arrangement reducing working hours temporarily, sometimes supported by government assistance to preserve jobs during weak demand.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c7d2103fed985dc7245971', 'Simple random sampling', ARRAY[]::text[], 'A procedure giving each eligible unit, or every possible sample of a given size under the stated design, an equal chance of selection.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7c177ef18b21e4832ec385', 'Single Resolution Mechanism', ARRAY[]::text[], 'The European framework for managing certain failing banks in participating countries using common resolution procedures.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4d496c228e23ba43a65f7b', 'Single Supervisory Mechanism', ARRAY[]::text[], 'The European system under which the ECB and national authorities jointly supervise banks in participating countries.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f427574d9f767b07afe9b1', 'Sovereign yield spread', ARRAY[]::text[], 'The difference between yields on government bonds from two issuers or a government bond and a reference security of similar maturity.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_5a4b860edd2808ce315358', 'Special drawing rights', ARRAY[]::text[], 'An international reserve asset created by the IMF whose value is based on a basket of major currencies; it is not itself ordinary money.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0b334ebf76adc9cde1a921', 'Squared poverty gap index', ARRAY[]::text[], 'A poverty measure that gives greater weight to people furthest below the poverty threshold by squaring individual shortfalls.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_83f786d6d4b36482130274', 'Standard normal distribution', ARRAY[]::text[], 'The normal probability distribution with mean zero and standard deviation one, used to standardise observations and estimates.', 'https://openstax.org/books/introductory-statistics-2e/pages/6-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_7d5c8f6da3275fd56e2b6a', 'Standardised score', ARRAY[]::text[], 'A value showing how many standard deviations an observation lies above or below the relevant mean.', 'https://openstax.org/books/introductory-statistics-2e/pages/6-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c3faf4c2e182134626a381', 'Standing facility', ARRAY[]::text[], 'A central-bank lending or deposit arrangement available to eligible counterparties at specified rates and conditions.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_aae2d83284dd5d37f10676', 'Statistical estimator', ARRAY[]::text[], 'A rule that uses sample observations to calculate an estimate of a population quantity.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_900030f4fe714c28585517', 'Statistical outlier detection', ARRAY[]::text[], 'The use of defined rules or diagnostics to flag observations that are unusual relative to a fitted model or distribution.', 'https://openstax.org/books/introductory-statistics-2e/pages/12-3-the-regression-equation', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4a16f468ffa46d041fa1a3', 'Statistical power', ARRAY[]::text[], 'The probability that a test rejects a false null hypothesis under a specified alternative, with larger values indicating greater detection ability.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_198c5e831be645774a11a5', 'Stock fund', ARRAY[]::text[], 'An investment fund that invests primarily in company shares rather than debt securities or cash.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ab3c788e7e84699abbf7a3', 'Stratified random sampling', ARRAY[]::text[], 'A sampling design dividing a population into defined subgroups and selecting observations randomly within each subgroup.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_9dd8e88ba619ae9723a6ff', 'Student''s t-distribution', ARRAY[]::text[], 'A family of symmetric probability distributions with heavier tails than the normal, used for inference when population variance is estimated.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_efca51ba4dc266eb34dfdf', 'Surrender charge', ARRAY[]::text[], 'A fee imposed when money is withdrawn from certain annuity or insurance products before a specified holding period ends.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_405d30615ecaef237b6e6a', 'Survey nonresponse', ARRAY[]::text[], 'The failure of selected people or businesses to supply requested data, which may introduce bias if respondents differ from nonrespondents.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d8d5361aacea8cd67bc401', 'Survey reference period', ARRAY[]::text[], 'The specific week, month or other interval about which participants provide information in a statistical survey.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b3af582dacc33e49750803', 'Systematic random sampling', ARRAY[]::text[], 'A method selecting units from an ordered list at regular intervals after an initial random start, with possible bias if the list has a repeating pattern.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_81c864f5c4e627fea129d5', 'Systemic oversight', ARRAY[]::text[], 'The assessment of risks affecting a financial system as a whole, including how stress can spread across institutions and markets.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d693ef5e1c231e3e0b1de7', 'TARGET Instant Payment Settlement', ARRAY[]::text[], 'A Eurosystem infrastructure that allows participating providers to settle eligible instant payments in central-bank money.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ebdd8553624bfca436ca9c', 'TARGET services', ARRAY[]::text[], 'The Eurosystem''s integrated services supporting large-value payments, securities settlement and instant payments in central-bank money.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d200dd6d4b1c313080aaf0', 'Target-date fund', ARRAY[]::text[], 'A diversified investment fund that generally shifts its asset allocation toward lower risk as a specified target year approaches.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b0a72eb837cd75a143ab58', 'TARGET2-Securities', ARRAY[]::text[], 'A European platform enabling harmonised securities settlement in central-bank money across participating markets.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d55b7ebea9bba6610acbdf', 'Technical default', ARRAY[]::text[], 'The failure to meet a contractual obligation other than a scheduled principal or interest payment, potentially triggering remedies under the contract.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_c1e523ef54bfc9a6d7796d', 'Temporary-help employment', ARRAY[]::text[], 'Jobs in which an agency employs workers and assigns them to perform tasks for client organisations.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_4a405f43c33f706232431b', 'Third quartile', ARRAY[]::text[], 'The value marking approximately the 75th percentile of ordered observations, below which about three quarters of the data lie.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_207f0b4aa0b3f97c98f99c', 'Total factor productivity', ARRAY[]::text[], 'The efficiency with which an economy or industry combines multiple inputs to produce output, estimated after accounting for measured input contributions.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0f4289d20f188e6ec1012b', 'Total fertility rate', ARRAY[]::text[], 'The average number of children a woman would have during her lifetime if current age-specific fertility rates persisted.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_a56b65e5471bff6c0b4175', 'Total job separations', ARRAY[]::text[], 'The sum of voluntary resignations, employer-initiated layoffs and other job endings during a reference period.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_ba7b558e22434cfe88324e', 'Transaction settlement cycle', ARRAY[]::text[], 'The agreed interval between a trade being executed and the delivery of securities and payment that completes it.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_45dab8b1c160493514e86d', 'Transfer agent', ARRAY[]::text[], 'A company or institution responsible for maintaining records of security ownership and processing transfers, distributions or related transactions.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_eb717aee7b1ce981e2a447', 'Transferable security', ARRAY[]::text[], 'A financial instrument, such as a share or bond, that can be traded or transferred under the rules of the relevant market.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_1787bf0a32a9e8f153dd88', 'Tri-party repurchase agreement', ARRAY[]::text[], 'A secured financing transaction in which a third-party agent assists with collateral selection, custody and administration.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_87e0d1254c36fb8ea25962', 'Two-sided hypothesis test', ARRAY[]::text[], 'A test assessing departures from a null value in either direction rather than limiting the alternative to an increase or decrease.', 'https://openstax.org/books/introductory-statistics-2e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d794b2cee193f545fee611', 'Under-five mortality rate', ARRAY[]::text[], 'The probability that a newborn dies before their fifth birthday, conventionally expressed per 1,000 live births.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_64a9493978dcf5ba96ce60', 'Unemployment duration', ARRAY[]::text[], 'The length of time a jobless person has been seeking work, usually measured in weeks under a survey''s definition.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_62d7558641df9eb6d98a2d', 'Unemployment inflow', ARRAY[]::text[], 'People newly entering unemployment from work or from outside the labour force during a specified period.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_2f0c860eeb06c6326237f3', 'Unemployment outflow', ARRAY[]::text[], 'People leaving unemployment by entering work or moving outside the active labour force over a period.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e1adfb9dcd44861b038f44', 'Uniform distribution', ARRAY[]::text[], 'A distribution in which all values in a defined interval or all listed outcomes have equal density or probability, respectively.', 'https://openstax.org/books/introductory-statistics-2e/pages/4-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_48faf2e80fffdf8f68a19e', 'Union coverage rate', ARRAY[]::text[], 'The share of employees whose pay or working conditions are governed by a union-negotiated agreement, including some who are not union members.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_0bf43aff1504d43131e650', 'Unsecured interbank lending', ARRAY[]::text[], 'A short-term loan from one bank to another without specific pledged collateral, carrying credit risk to the lender.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_35f1ee8e5a881f61321386', 'Urban population growth rate', ARRAY[]::text[], 'The yearly percentage change in the number of residents classified as urban, influenced by migration, natural increase and reclassification.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_af028068e1dcd2df67023f', 'Urban population share', ARRAY[]::text[], 'The percentage of a country''s population classified as living in urban areas according to its statistical definition.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_83792e00aae244314ab4c6', 'Usual weekly earnings', ARRAY[]::text[], 'Pay workers normally receive in a typical week, as distinct from earnings in a particular reference week.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_df47a552df545b4944d041', 'Variable annuity', ARRAY[]::text[], 'An insurance contract whose value or future payments vary with the performance of chosen investment options, subject to fees and guarantees.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_d3dc71b7a10af0bcbf490b', 'Variation margin', ARRAY[]::text[], 'Collateral transferred to reflect changes in the market value of a derivative or other margined position after it is established.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f2382212ea1d9b73ffb480', 'Wage and salary employment', ARRAY[]::text[], 'Paid employment in which workers receive compensation from an employer rather than operating their own business.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_dd3e7404a2f38734a27870', 'Wash sale', ARRAY[]::text[], 'A transaction in which an investor sells a security at a loss and rapidly acquires substantially identical exposure, potentially affecting tax deductions under applicable law.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_fdd9ff7eb4ebbb38ce8500', 'Water stress level', ARRAY[]::text[], 'The proportion of available renewable freshwater resources withdrawn after accounting for environmental water needs.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_65e5189dcc509a1e241a9f', 'Wealth-to-income ratio', ARRAY[]::text[], 'The stock of measured wealth relative to annual income, used to compare accumulated resources with the flow of earnings.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_b74eb674a1a90b78bd6cca', 'Weighted arithmetic mean', ARRAY[]::text[], 'An average assigning observations different weights, for example reflecting population shares or expenditure proportions.', 'https://openstax.org/books/introductory-statistics-2e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_a37fda9cf3219205e07e1e', 'Wholesale funding', ARRAY[]::text[], 'Bank or corporate financing raised through institutional markets, including deposits, debt securities and secured borrowing.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_be9ceec09f64b1080b21fc', 'Wholesale payment', ARRAY[]::text[], 'A transfer generally involving financial institutions or large commercial transactions rather than ordinary consumer purchases.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_6bbfa0c3628bb3eeb635c7', 'Work stoppage', ARRAY[]::text[], 'A temporary cessation of work caused by an industrial dispute, including strikes and lockouts.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_31b76f29a4bad327d01f04', 'Workforce attachment', ARRAY[]::text[], 'The extent to which a person remains engaged in paid work or job search across time, often assessed through employment histories.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e6cca8d7b39811cf811b34', 'Workplace absenteeism rate', ARRAY[]::text[], 'The share of scheduled working time missed by employees for reasons such as illness or personal obligations.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_f2284936a4acb42ac1d0ad', 'Workplace fatality rate', ARRAY[]::text[], 'The number of work-related deaths relative to the size or exposure of a defined workforce.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_5277270f685b6099d4e9c5', 'Workplace productivity', ARRAY[]::text[], 'Output generated relative to labour time or another specified input in a workplace, influenced by equipment and organisation.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_58bfcf44db6e2fd412f252', 'Workweek length', ARRAY[]::text[], 'The average number of hours employees work over a standard week, which can change with overtime or part-time hiring.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_24bc97b217c01ac361d224', 'Year-on-year wage growth', ARRAY[]::text[], 'The percentage increase in pay relative to the same period one year earlier, reducing some effects of seasonal fluctuations.', 'https://www.bls.gov/bls/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_902d926098d608d99f28f8', 'Yield to call', ARRAY[]::text[], 'The annualised return implied by a callable bond''s price and promised payments if the issuer redeems it on a specified call date.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_8d6ea5b9cdd3d9223a918d', 'Youth dependency ratio', ARRAY[]::text[], 'The number of people below the defined working-age threshold relative to the working-age population.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg2615_e0f89b40bde18407a4f3fe', 'Youth literacy rate', ARRAY[]::text[], 'The share of young people in a specified age band who can read and write a short, simple statement under the relevant survey definition.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc'))
